import{_ as t}from"./chunks/nahrada_uzivatele.RPcfS4Lh.js";import{_ as o,o as a,c as n,aa as r}from"./chunks/framework.BAs_AphD.js";const i="/buildary-help-preview/academy/img/projektovy-tym/02.webp",d="/buildary-help-preview/academy/img/projektovy-tym/08.webp",l="/buildary-help-preview/media/cs/diary/roleclenu.png",b=JSON.parse('{"title":"Projektový tým: firmy a lidé","description":"","frontmatter":{"title":"Projektový tým: firmy a lidé"},"headers":[],"relativePath":"diary/projectteam.md","filePath":"diary/projectteam.md","lastUpdated":1794209661000}'),s={name:"diary/projectteam.md"};function v(m,e,p,k,u,h){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="projektovy-tym-firmy-a-lide" tabindex="-1">Projektový tým: firmy a lidé <a class="header-anchor" href="#projektovy-tym-firmy-a-lide" aria-label="Permalink to &quot;Projektový tým: firmy a lidé&quot;">​</a></h1><p>Projektový tým tvoří všechny firmy a lidé, kteří mají přístup na stavbu. Z jeho členů pak vybíráte oprávněné osoby deníků, Řešitele a Schvalovatele úkolů i ty, kdo zadávají a schvalují soupisy provedených prací.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/projektovy-tym">Přidat lidi a firmy do týmu stavby</a> v Akademii.</p><h2 id="kde-projektovy-tym-najdete" tabindex="-1">Kde projektový tým najdete <a class="header-anchor" href="#kde-projektovy-tym-najdete" aria-label="Permalink to &quot;Kde projektový tým najdete&quot;">​</a></h2><p>Otevřete <strong>Nastavení stavby</strong> (ikona ozubeného kola v levém panelu) a záložku <strong>Projektový tým</strong>. Upravovat ho smí ten, kdo má na stavbě kompetenci <strong>Administrace stavby</strong> nebo <strong>Správa projektového týmu</strong>, případně odpovídající právo v doméně – viz <a href="/buildary-help-preview/diary/userpermissions">Kdo co smí v deníku</a>.</p><table tabindex="0"><thead><tr><th>Záložka</th><th>K čemu slouží</th></tr></thead><tbody><tr><td><strong>Členové projektu</strong></td><td>Lidé na stavbě, jejich firma, výchozí role a e-mailová oznámení.</td></tr><tr><td><strong>Firmy</strong></td><td>Firmy, které se stavby účastní.</td></tr><tr><td><strong>Role členů</strong></td><td>Role lidí a oprávnění, která z nich vyplývají.</td></tr><tr><td><strong>Role firem</strong></td><td>Číselník rolí firem (stavebník, zhotovitel…).</td></tr><tr><td><strong>Práva v denících</strong></td><td>Přehled, kdo má v kterém deníku jakou roli.</td></tr><tr><td><strong>Náhrada uživatele</strong></td><td>Nahrazení člověka, který ze stavby odchází, jiným.</td></tr></tbody></table><p>Začněte firmami, pak přidávejte lidi – každého člena přiřazujete k firmě.</p><div class="tip custom-block"><p class="custom-block-title">Projektový tým, nebo doména?</p><p>Do <a href="/buildary-help-preview/firstofall/domain">firemní domény</a> patří jen zaměstnanci vaší firmy. Lidi z jiných firem (stavebník, technický dozor, podzhotovitelé) přidávejte jen do projektového týmu konkrétní stavby. Uživatel, který je ve stejné doméně jako stavba, má na stavbě i práva, která mu byla přidělena v doméně.</p></div><h2 id="firmy" tabindex="-1">Firmy <a class="header-anchor" href="#firmy" aria-label="Permalink to &quot;Firmy&quot;">​</a></h2><p>Jako první firma je v seznamu vždy firma z domény, do které stavba patří. Další firmy přidáte tlačítkem <strong>Přidat</strong>.</p><figure class="shot" style="--w:760px;"><img src="'+i+'" alt="Formulář Nová firma s tlačítky ARES a Slovensko Digital" loading="lazy"></figure><ul><li><strong>Název firmy</strong> a <strong>IČO</strong> – po vyplnění názvu nebo IČO klikněte na <strong>ARES</strong> (české firmy) nebo <strong>Slovensko Digital</strong> (slovenské firmy) a ostatní údaje se doplní z veřejného rejstříku.</li><li><strong>Role firmy</strong> – povinná, vyberete ji z číselníku na záložce Role firem.</li><li><strong>Obchodní rejstřík</strong>, <strong>Předmět činnosti na stavbě</strong>, <strong>Ulice</strong>, <strong>Město</strong>, <strong>PSČ</strong> – další údaje o firmě.</li></ul><p>Firmy z projektového týmu pak vybíráte v deníku, například firmu, která deník vede.</p><h2 id="role-firem" tabindex="-1">Role firem <a class="header-anchor" href="#role-firem" aria-label="Permalink to &quot;Role firem&quot;">​</a></h2><p>Číselník obsahuje nejčastější role firem na stavbě, například <strong>Stavebník</strong> nebo <strong>Zhotovitel</strong>. Můžete přidat vlastní role nebo stávající přejmenovat.</p><div class="warning custom-block"><p class="custom-block-title">Přejmenovávejte opatrně</p><p>Výchozí roli přejmenujte jen tak, aby se nezměnil její význam. Potřebujete-li roli s jiným významem, vytvořte novou.</p></div><h2 id="clenove-projektu" tabindex="-1">Členové projektu <a class="header-anchor" href="#clenove-projektu" aria-label="Permalink to &quot;Členové projektu&quot;">​</a></h2><p>Nového člena přidáte na záložce <strong>Členové projektu</strong> tlačítkem <strong>Přidat</strong>.</p><figure class="shot" style="--w:760px;"><img src="'+d+'" alt="Formulář Nový člen projektu s e-mailovými oznámeními a přiřazením k deníkům" loading="lazy"></figure><table tabindex="0"><thead><tr><th>Pole</th><th>Význam</th></tr></thead><tbody><tr><td><strong>E-mail</strong></td><td>Podle e-mailu se člen spáruje s účtem First Account. Má-li už člověk účet v Buildary, jméno, příjmení a telefon se doplní z jeho účtu.</td></tr><tr><td><strong>Jméno</strong>, <strong>Příjmení</strong>, <strong>Telefon</strong></td><td>Kontaktní údaje.</td></tr><tr><td><strong>Firma</strong></td><td>Firma, za kterou člověk na stavbě vystupuje. Jeden člověk může patřit i k více firmám. Chybí-li firma v nabídce, přidejte ji nejdřív na záložce Firmy.</td></tr><tr><td><strong>Výchozí role v oprávněných osobách</strong></td><td>Role určuje oprávnění člena na stavbě – v deníku, v úkolech i v soupisech. V konkrétním deníku můžete člověku dát jinou roli.</td></tr><tr><td><strong>Emailové oznámení</strong></td><td>Kdy a jak bude člen dostávat e-maily – viz <a href="#e-mailova-oznameni">E-mailová oznámení</a>.</td></tr><tr><td><strong>Přiřazení uživatele k deníku stavby</strong></td><td>Zaškrtněte deníky, do kterých má člen rovnou přibýt jako oprávněná osoba. Seznam deníků můžete filtrovat.</td></tr></tbody></table><p>Po uložení odejde členovi e-mailem pozvánka. Obsahuje odkaz do aplikace a pro toho, kdo ještě účet nemá, i odkaz na registraci. Dokud si člen účet neaktivuje, je u něj v seznamu výstražný trojúhelník.</p><p>Údaje člena později upravíte ikonou tužky na konci řádku.</p><div class="info custom-block"><p class="custom-block-title">Fakturace</p><p>Do fakturace stavby se započítávají všichni uživatelé, kteří byli do projektového týmu přidáni – i ti, kterým jste přístup později ukončili. Odebráním přístupu tedy neušetříte.</p></div><h3 id="pristup-na-stavbu-a-do-deniku" tabindex="-1">Přístup na stavbu a do deníku <a class="header-anchor" href="#pristup-na-stavbu-a-do-deniku" aria-label="Permalink to &quot;Přístup na stavbu a do deníku&quot;">​</a></h3><p>Člen projektového týmu má přístup na stavbu, ale do deníku smí, jen když je v něm <strong>oprávněnou osobou</strong>. Oprávněnou osobou ho uděláte:</p><ul><li>zaškrtnutím deníku v části <strong>Přiřazení uživatele k deníku stavby</strong> přímo ve formuláři člena,</li><li>v Identifikačních údajích deníku na záložce <strong>Oprávněné osoby</strong> – krok za krokem v lekci <a href="/buildary-help-preview/akademie/opravnene-osoby">Přidat oprávněnou osobu do deníku</a>,</li><li>automaticky, pokud má stavba zapnutou volbu <strong>Stavba s jedním deníkem</strong> (viz <a href="/buildary-help-preview/diary/projectsetup#stavba-s-jednim-denikem">Založit stavbu</a>).</li></ul><h3 id="e-mailova-oznameni" tabindex="-1">E-mailová oznámení <a class="header-anchor" href="#e-mailova-oznameni" aria-label="Permalink to &quot;E-mailová oznámení&quot;">​</a></h3><p>Pro každý modul nastavíte, zda a jak bude člen dostávat e-maily.</p><table tabindex="0"><thead><tr><th>Oznámení</th><th>Volby</th></tr></thead><tbody><tr><td><strong>E-mailové oznámení - Stavební deník</strong> (o nových a upravených Dalších záznamech)</td><td><strong>Žádné</strong> – e-maily nechodí. <strong>HTML email</strong> – e-mail přijde vždy, když někdo přidá nebo upraví Další záznam. <strong>Dle nastavení deníku</strong> – v Identifikačních údajích každého deníku určíte, ze kterých deníků mají oznámení chodit. Hodí se na stavbách s více deníky.</td></tr><tr><td><strong>E-mailové oznámení - Ukončení stavby</strong></td><td><strong>Žádné</strong>, nebo <strong>HTML email</strong> – e-mail přijde, když někdo stavbu ukončí.</td></tr><tr><td><strong>E-mailové oznámení - Management úkolů</strong></td><td>Oznámení o úkolech, které člen řeší nebo schvaluje – viz <a href="/buildary-help-preview/tickets/notification">Upozornění na úkoly</a>.</td></tr><tr><td><strong>E-mailové oznámení - Soupisy provedených prací</strong></td><td>Oznámení o soupisech – viz <a href="/buildary-help-preview/performedworks/competences#e-mailova-oznameni">Kompetence pro soupisy</a>.</td></tr></tbody></table><p>Při volbě <strong>Žádné</strong> nebo <strong>HTML email</strong> u Stavebního deníku platí nastavení pro všechny deníky stavby a v Identifikačních údajích deníku ho už nezměníte.</p><h2 id="role-clenu" tabindex="-1">Role členů <a class="header-anchor" href="#role-clenu" aria-label="Permalink to &quot;Role členů&quot;">​</a></h2><p>Na záložce <strong>Role členů</strong> je seznam rolí lidí na stavbě (Administrátor, Autorský dozor, Čtenář deníku, Koordinátor BOZP…) a u každé role zaškrtnutá oprávnění. Role jsou společné pro všechny moduly – podle nich se řídí práva ve Stavebním deníku, v Managementu úkolů i v Soupisech provedených prací.</p><figure class="shot" style="--w:760px;"><img src="'+l+'" alt="Záložka Role členů s oprávněními jednotlivých rolí" loading="lazy"></figure><p>Můžete vytvářet vlastní role a upravovat oprávnění výchozích rolí. Výchozí roli přejmenujte jen tehdy, když jde o formální změnu názvu a význam role zůstává stejný.</p><p>Co jednotlivá oprávnění znamenají:</p><ul><li>Stavební deník a stavba: <a href="/buildary-help-preview/diary/userpermissions">Kdo co smí v deníku</a>.</li><li>Úkoly (vidět všechny úkoly, zadávat nové úkoly): <a href="/buildary-help-preview/tickets/permissions">Kdo co smí v úkolech</a>.</li><li>Soupisy (zadání a schvalování SPP): <a href="/buildary-help-preview/performedworks/competences">Kompetence pro soupisy</a>.</li></ul><h2 id="prava-v-denicich" tabindex="-1">Práva v denících <a class="header-anchor" href="#prava-v-denicich" aria-label="Permalink to &quot;Práva v denících&quot;">​</a></h2><p>Záložka <strong>Práva v denících</strong> ukazuje na jednom místě všechny uživatele, deníky stavby a role, které v nich mají. Krok za krokem: <a href="/buildary-help-preview/akademie/prava-v-denicich">Zjistit, kdo má jaká práva v denících</a> v Akademii.</p><h2 id="nahrada-uzivatele" tabindex="-1">Náhrada uživatele <a class="header-anchor" href="#nahrada-uzivatele" aria-label="Permalink to &quot;Náhrada uživatele&quot;">​</a></h2><p>Když člověk ze stavby odchází a jeho práci přebírá jiný, použijte záložku <strong>Náhrada uživatele</strong>. Zadejte e-mail původního a nového uživatele a klikněte na <strong>Nahradit</strong>. Původní uživatel se zneplatní a nový ho nahradí ve všech denících, do kterých měl původní uživatel přístup.</p><figure class="shot" style="--w:600px;"><img src="'+t+'" alt="Záložka Náhrada uživatele s poli pro e-mail původního a nového uživatele" loading="lazy"></figure>',41)])])}const j=o(s,[["render",v]]);export{b as __pageData,j as default};
